from decimal import Decimal


def _line_number_value(row: dict) -> Decimal:
    """Return LINE_NO using legacy numeric empty-string semantics."""
    value = row.get("LINE_NO", "")
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted order lines and assign contiguous per-order line numbers."""
    surviving = [
        (index, row)
        for index, row in enumerate(lines)
        if row.get("DEL_FLG", "") != "Y"
    ]

    surviving.sort(
        key=lambda item: (
            str(item[1].get("ORD_ID", "")),
            _line_number_value(item[1]),
            item[0],
        )
    )

    result: list[dict] = []
    current_order_id: str | None = None
    next_line_no = 0

    for _, row in surviving:
        order_id = str(row.get("ORD_ID", ""))
        if order_id != current_order_id:
            current_order_id = order_id
            next_line_no = 1
        else:
            next_line_no += 1

        renumbered_row = dict(row)
        renumbered_row["LINE_NO"] = next_line_no
        result.append(renumbered_row)

    return result
